/**
 * LIVE semantic layer: real data from ClickHouse database `nearesis_live` (see services/ingestion/migrations-live).
 * Served by a separate Cube instance (`cube-live`, port 4001) so the fixture cubes, the fixture registry and the S01-S16
 * golden tests are untouched. Metric metadata lives in registry/live/metrics.live.v1.json (generated by scripts/gen-live.ts).
 */
import type { CubeDef } from "../model/definition.ts";

export const LIVE_WINDOW = { from: "2025-11-10", to: "2026-11-09" } as const;
export const LIVE_CUBE_URL_DEFAULT = "http://127.0.0.1:4001";
export const LIVE_DATABASE = "nearesis_live";

const label = {
  name: "source_label",
  sql: "source_label",
  type: "string" as const,
  description: "Always LIVE in this layer: real provider data",
};

export const LIVE_CUBES: CubeDef[] = [
  {
    name: "near_daily_tx_live_facts",
    table: "near_daily_tx",
    view: "near_daily_tx_live",
    timeColumn: "block_date",
    dimensions: [label],
    measures: [
      {
        name: "tx_count",
        type: "sum",
        sql: "tx_count",
        description: "Transactions converted to receipts per UTC day (LIVE, BigQuery)",
      },
      {
        name: "distinct_signer_proxy",
        type: "sum",
        sql: "distinct_signer_proxy",
        description: "Daily distinct signer accounts (a proxy, not humans). NEVER summed across days",
      },
    ],
    rollups: [],
  },
  {
    name: "contract_interactions_live_facts",
    table: "contract_interactions",
    view: "contract_interactions_live",
    timeColumn: "block_date",
    dimensions: [
      label,
      {
        name: "receiver_account_id",
        sql: "receiver_account_id",
        type: "string",
        description: "Receiver contract account (only receivers with >= 100 function calls that day)",
      },
    ],
    measures: [
      {
        name: "interactions",
        type: "sum",
        sql: "interactions",
        description:
          "FunctionCall actions received by the listed contracts per UTC day (LIVE, >= 100/day receivers)",
      },
    ],
    rollups: [],
  },
  {
    name: "price_candles_live_facts",
    table: "price_candles",
    view: "price_candles_live",
    timeColumn: "day",
    select:
      "SELECT * FROM price_candles FINAL ORDER BY update_vintage DESC LIMIT 1 BY provider, coin_id, quote_currency, `interval`, bucket_start",
    dimensions: [
      label,
      { name: "coin_id", sql: "coin_id", type: "string", description: "Coin identifier" },
      {
        name: "basis",
        sql: "basis",
        type: "string",
        description: "How daily OHLC was derived (hourly samples)",
      },
    ],
    measures: [
      {
        name: "close_price_usd",
        type: "avg",
        sql: "close",
        filter: "{CUBE}.quote_currency = 'usd'",
        description: "Daily close in USD: last of 24 hourly samples (LIVE, CoinGecko)",
      },
    ],
    rollups: [],
  },
  {
    name: "intents_swaps_live_facts",
    table: "intents_swaps",
    view: "intents_swaps_live",
    timeColumn: "created_day",
    dimensions: [
      label,
      { name: "status", sql: "status", type: "string", description: "Latest provider status" },
      {
        name: "privacy_era",
        sql: "privacy_era",
        type: "string",
        description: "public | private_settlement (created on/after 2026-10-27)",
      },
    ],
    measures: [
      {
        name: "swap_count",
        type: "count",
        description: "1Click swaps by creation day, latest status (LIVE)",
      },
      {
        name: "completed_swap_count",
        type: "count",
        filter: "{CUBE}.status = 'SUCCESS'",
        description: "Swaps whose latest status is SUCCESS (LIVE)",
      },
    ],
    rollups: [],
  },
];
